/// 묶음 판정에 쓰는 상품 값 — 출고지와 배송 정책입니다.
class DeliveryBundleProduct {
  /// [DeliveryBundleProduct]을 만듭니다.
  const DeliveryBundleProduct(
      {required this.deliveryType,
      required this.deliveryFee,
      required this.conditionalFreeAmount,
      this.shippingAddressId,
      this.fulfillmentType});

  /// `deliveryType` 값입니다.
  final DeliveryType deliveryType;

  /// `deliveryFee` 값입니다.
  final int deliveryFee;

  /// `conditionalFreeAmount` 값입니다.
  final int? conditionalFreeAmount;

  /// 출고지 주소 id(`seller_addresses`). null이면 상점 기본 출고지를 쓰는 상품끼리 한 묶음입니다.
  final String? shippingAddressId;

  /// 상품 유형 (이슈 #48). 생략·null이면 배송 상품입니다. 배송이 필요 없는 유형은 묶음을 만들지 않습니다.
  /// 줄(`DeliveryFeeLine.fulfillmentType`)에 값이 있으면 그 값이 이깁니다.
  final FulfillmentType? fulfillmentType;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {
        'deliveryType': deliveryType,
        'deliveryFee': deliveryFee,
        'conditionalFreeAmount': conditionalFreeAmount,
        if (shippingAddressId != null) 'shippingAddressId': shippingAddressId,
        if (fulfillmentType != null) 'fulfillmentType': fulfillmentType
      };
}

/// 계산에 넣는 한 줄 — 주문상품·장바구니 항목·주문서 항목이 이 형태로 들어옵니다.
class DeliveryFeeLine {
  /// [DeliveryFeeLine]을 만듭니다.
  const DeliveryFeeLine({required this.productId, required this.amount, this.fulfillmentType, this.fulfillmentMethod});

  /// `productId` 값입니다.
  final String productId;

  /// 상품 금액 (할인 반영 단가 × 수량).
  final int amount;

  /// 이 줄의 상품 유형 — 주문서 스냅샷 값입니다(이슈 #48). 주면 상품의 현재 유형보다 우선합니다. 주문서를 만든 뒤 셀러가
  /// 유형을 바꿔도 결제 시작의 견적과 주문상품 스냅샷이 같은 유형을 보게 합니다. 생략하면 상품 값을 씁니다.
  final FulfillmentType? fulfillmentType;

  /// 이 줄의 이행 방식(이슈 #115) — 배송지가 없는 방식(방문 수령)은 묶음을 만들지 않습니다. 생략하면 유형 규칙만 봅니다.
  final String? fulfillmentMethod;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {
        'productId': productId,
        'amount': amount,
        if (fulfillmentType != null) 'fulfillmentType': fulfillmentType,
        if (fulfillmentMethod != null) 'fulfillmentMethod': fulfillmentMethod
      };
}

/// [String] 스키마입니다. 값은 `FREE`·`STORE_THRESHOLD`·`CONDITIONAL`입니다.
///
/// 기본 배송비를 면제한 근거 — 면제하지 않았으면 null입니다.
///
/// 환불 정산이 근거를 구분해야 합니다. 조건부 무료 기준 미달 차감은 **상품별 조건부 무료(`CONDITIONAL`)로
/// 면제된 묶음만** 대상입니다. 상점 전체 무료 기준(`STORE_THRESHOLD`)이나 무료배송 상품(`FREE`)은 셀러가
/// 배송비를 받지 않기로 한 것이므로, 일부 취소로 기준이 깨져도 구매자에게 배송비를 물리지 않습니다.
///
/// 세 값이 겹치면 `FREE` → `STORE_THRESHOLD` → `CONDITIONAL` 순으로 센 근거를 남깁니다.
final ZodEnum deliveryFeeWaiverSchema = z.enum_(['FREE', 'STORE_THRESHOLD', 'CONDITIONAL']);

/// DeliveryFeeWaiver 값입니다.
///
/// 값은 `FREE`·`STORE_THRESHOLD`·`CONDITIONAL`입니다.
typedef DeliveryFeeWaiver = String;

/// 묶음 하나의 견적.
class DeliveryBundleQuote {
  /// [DeliveryBundleQuote]을 만듭니다.
  const DeliveryBundleQuote(
      {required this.bundleKey,
      required this.productIds,
      required this.fee,
      required this.waivedBy,
      required this.listFee,
      required this.freeThreshold,
      required this.remoteSurcharge});

  /// `bundleKey` 값입니다.
  final String bundleKey;

  /// 이 묶음에 든 상품 id — 스냅샷 검증과 상점 플랫폼 안내에 씁니다.
  final List<String> productIds;

  /// 실제 청구한 기본 배송비 — 무료배송·무료 기준 충족이면 0.
  final int fee;

  /// 기본 배송비를 면제한 근거. 청구했으면 null.
  final DeliveryFeeWaiver? waivedBy;

  /// 배송비 정가 — 조건부 무료 미달 차감액의 상한입니다.
  final int listFee;

  /// 묶음 조건부 무료 기준액. 조건부 무료가 아니면 null.
  final int? freeThreshold;

  /// 이 묶음에 붙은 지역 추가 배송비.
  final int remoteSurcharge;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {
        'bundleKey': bundleKey,
        'productIds': productIds,
        'fee': fee,
        'waivedBy': waivedBy,
        'listFee': listFee,
        'freeThreshold': freeThreshold,
        'remoteSurcharge': remoteSurcharge
      };
}

/// 배송비 견적 — 합계와 묶음 내역.
class DeliveryQuote {
  /// [DeliveryQuote]을 만듭니다.
  const DeliveryQuote(
      {required this.bundles,
      required this.baseFee,
      required this.remoteSurcharge,
      required this.deliveryFee,
      required this.remoteArea,
      required this.freeByThreshold,
      required this.shippableAmount,
      required this.requiresShipping});

  /// `bundles` 값입니다.
  final List<DeliveryBundleQuote> bundles;

  /// 기본 배송비 합계 (지역 추가 제외).
  final int baseFee;

  /// 지역 추가 배송비 합계.
  final int remoteSurcharge;

  /// 청구할 배송비 총액 = `baseFee` + `remoteSurcharge`.
  final int deliveryFee;

  /// `remoteArea` 값입니다.
  final RemoteArea remoteArea;

  /// 상점 전체 무료 기준(`freeThreshold`) 충족으로 기본 배송비를 면제했는지입니다.
  final bool freeByThreshold;

  /// 배송이 필요한 줄의 상품 금액 합 — 상점 전체 무료 기준의 판정 금액입니다(이슈 #48). 비실물 줄은 빠집니다.
  /// 주문 상품 금액 합(`productAmount`)과 다를 수 있습니다.
  final int shippableAmount;

  /// 배송이 필요한 줄이 하나라도 있는지입니다 — 배송 묶음이 하나라도 있는가입니다. false면 배송지를 받지 않습니다.
  final bool requiresShipping;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {
        'bundles': bundles,
        'baseFee': baseFee,
        'remoteSurcharge': remoteSurcharge,
        'deliveryFee': deliveryFee,
        'remoteArea': remoteArea,
        'freeByThreshold': freeByThreshold,
        'shippableAmount': shippableAmount,
        'requiresShipping': requiresShipping
      };
}

/// DeliveryQuoteInput 값입니다.
class DeliveryQuoteInput {
  /// [DeliveryQuoteInput]을 만듭니다.
  const DeliveryQuoteInput({required this.lines, required this.productOf, required this.policy, this.zipCode});

  /// `lines` 값입니다.
  final List<DeliveryFeeLine> lines;

  /// 상품 배송 정책 조회 — 못 읽은 상품은 계산에서 빠집니다(배송비를 만들어 붙이지 않습니다).
  final DeliveryBundleProduct? Function(String) productOf;

  /// `policy` 값입니다.
  final ShippingPolicy policy;

  /// 배송지 우편번호. 아직 모르면 생략합니다 — 지역 추가 배송비 0으로 계산합니다.
  final String? zipCode;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() =>
      {'lines': lines, 'productOf': productOf, 'policy': policy, if (zipCode != null) 'zipCode': zipCode};
}
